export const EDITOR_DIALOG_HTML = "<dialog id=\"imageEditorDialog\" class=\"image-editor-dialog\" aria-labelledby=\"imageEditorTitle\">\n      <form method=\"dialog\" class=\"image-editor-form\" tabindex=\"-1\">\n        <header><div><span class=\"eyebrow\">選択した手順の画像</span><h2 id=\"imageEditorTitle\">画像を調整</h2></div><button type=\"button\" class=\"secondary\" data-editor-cancel aria-label=\"画像編集を閉じる\">閉じる</button></header>\n        <div class=\"image-editor-workspace\"><div class=\"image-editor-canvas-wrap\"><canvas id=\"imageEditorCanvas\" tabindex=\"0\" aria-label=\"編集する画像\"></canvas><p class=\"editor-help\">画像の上でドラッグして追加・移動できます</p></div><aside class=\"image-editor-tools\" aria-label=\"画像編集ツール\"><p data-editor-status role=\"status\" aria-live=\"polite\">画像を準備しています。</p><div class=\"tool-group\"><span class=\"tool-label\">追加するもの</span><div class=\"tool-grid\"><button type=\"button\" data-editor-tool=\"select\" aria-pressed=\"true\">選択</button><button type=\"button\" data-editor-tool=\"arrow\" aria-pressed=\"false\">矢印</button><button type=\"button\" data-editor-tool=\"text\" aria-pressed=\"false\">文字</button></div><details class=\"advanced-tools\"><summary>図形・黒塗り</summary><div class=\"tool-grid\"><button type=\"button\" data-editor-tool=\"rectangle\" aria-pressed=\"false\">四角形</button><button type=\"button\" data-editor-tool=\"ellipse\" aria-pressed=\"false\">円</button><button type=\"button\" data-editor-tool=\"mask\" aria-pressed=\"false\">黒塗り</button><button type=\"button\" data-editor-tool=\"crop\" aria-pressed=\"false\">切り抜き</button></div></details></div><div class=\"property-group\" hidden><label data-text-property>選択中の文字<textarea data-editor-text placeholder=\"文字を入力\"></textarea></label><label data-text-property>文字サイズ<input data-editor-font-size type=\"number\" min=\"10\" max=\"96\" step=\"1\" value=\"24\"></label><label data-color-property><span data-color-label>枠線の色</span><input data-editor-color type=\"color\" value=\"#087f7a\"><input data-editor-color-hex type=\"text\" value=\"#087f7a\" maxlength=\"7\" spellcheck=\"false\" inputmode=\"text\" aria-label=\"色のカラーコード\" placeholder=\"#087f7a\"></label></div><div class=\"selection-group\"><span class=\"tool-label\">追加した要素</span><div data-editor-selection aria-label=\"追加した文字や図形、黒塗り\"></div></div><p class=\"editor-help\">要素を選ぶと色などの設定が開きます。黒塗りのある画像は、保存時に文字・図形と一緒に画像へ統合します。隠した文字は編集データに残しません。</p></aside></div>\n        <footer class=\"image-editor-actions\"><span>画像へ適用してから、手順書を保存します</span><button type=\"button\" class=\"secondary\" data-editor-cancel>キャンセル</button><button type=\"button\" data-editor-save>変更を適用</button></footer>\n      </form>\n    </dialog>";
export const EDITOR_TOOLS_CSS = ".image-editor-dialog{height:100%;min-height:0;display:none;position:relative;inset:auto;margin:0;border:0;padding:0;background:#f2f6f7;width:100%;max-width:none;max-height:none;grid-column:2/4;grid-row:1;min-width:0;overflow:auto}.image-editor-dialog[open]{display:block}.image-editor-form{height:100%;display:flex;flex-direction:column}.image-editor-form>header{flex:none;min-height:70px;display:flex;align-items:center;justify-content:space-between;padding:12px 24px;border-bottom:1px solid var(--border);gap:12px}.image-editor-form>header h2{font-size:1.05rem}.image-editor-workspace{display:grid;grid-template-columns:minmax(0,1fr) 280px;flex:1;min-height:0}.image-editor-canvas-wrap{box-sizing:border-box;padding:22px;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;overflow:auto}#imageEditorCanvas{box-sizing:border-box;max-width:100%;max-height:calc(100dvh - 285px);width:auto;height:auto;object-fit:contain;touch-action:none;box-shadow:0 3px 12px #19303914;background:white;border:1px solid #ccdadd}.image-editor-tools{overflow:auto;background:white;border-left:1px solid var(--border);padding:18px;display:flex;flex-direction:column;gap:18px}.image-editor-tools>[data-editor-status]{font-size:.83rem;color:var(--teal);min-height:25px}.tool-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.tool-grid button{font-size:.8rem;padding:8px 4px;border:1px solid var(--border);background:#fff;color:var(--ink)}.tool-grid button[aria-pressed=true]{background:var(--teal);color:white;border-color:var(--teal)}.tool-label{display:block;font-size:.8rem;color:var(--muted);margin-bottom:7px}.property-group{display:grid;gap:12px;padding-top:14px;border-top:1px solid var(--border)}.property-group label{display:grid;gap:4px;font-size:.84rem}.property-group textarea{min-height:74px}.property-group input[type=color]{width:100%;min-height:44px;padding:4px}.selection-group [data-editor-selection]{display:grid;gap:5px;max-height:240px;overflow:auto}.selection-group [data-editor-selection]>div{display:flex;gap:4px}.selection-group button{font-size:.78rem;min-height:38px;padding:7px;flex:1;min-width:0;background:#f2f6f7;color:var(--ink);overflow:hidden;text-overflow:ellipsis}.selection-group button:last-child{flex:none;color:#a12f2b}.image-editor-actions{flex:none;display:flex;align-items:center;justify-content:flex-end;gap:10px;background:white;border-top:1px solid var(--border);padding:12px 20px;min-height:70px}.image-editor-actions>span{margin-right:auto;color:var(--muted);font-size:.75rem}.image-editor-dialog .editor-help{font-size:.78rem}.image-editor-canvas-wrap{position:relative}.image-editor-error{position:absolute;inset:20px;display:grid;align-content:center;justify-items:center;gap:16px;padding:24px;border:1px dashed #bc8d6f;border-radius:10px;background:#fff9f2;text-align:center;color:#713c16}.image-editor-error[hidden]{display:none!important}.image-editor-error button{background:#fff;border-color:#bc8d6f;color:#713c16}\n\nbutton.secondary,input,textarea,.tool-grid button,.selection-group button{border-color:#789099}.image-action-row button,.zoom-controls button{min-height:44px}.output-gate .save-state{white-space:normal;word-break:keep-all;overflow-wrap:anywhere}\n\n/* Keep the caption immediately beneath the image controls. */\n.screenshot-preview{max-height:calc(100dvh - 390px)}\n@media(max-width:768px){.screenshot-preview{max-height:36dvh}}\n.image-editor-tools .tool-grid button{white-space:nowrap;min-width:0}\n[data-replacement-action=add]{width:100%;margin-top:2px}[data-replacement-action=help]{margin:0}\n@media(max-width:1150px) and (min-width:769px){.image-editor-tools .tool-grid{grid-template-columns:repeat(2,minmax(66px,1fr))}}\n\n@media(max-width:760px){.image-editor-actions{flex-wrap:wrap}.image-editor-actions>span{display:block;flex-basis:100%;margin:0;font-size:.78rem}}\n@media(max-width:768px){.image-editor-dialog{height:100%;overflow:hidden}.image-editor-form{height:100%;min-height:0}.image-editor-workspace{display:block;min-height:0;overflow:auto}.image-editor-canvas-wrap{min-height:120px;overflow:visible}.image-editor-tools{overflow:visible}.image-editor-actions{position:static}}\n.image-editor-tools [data-editor-replacement-type]{min-height:44px}\n";
